// Assemble evidence package per cap 24m §10.1
const alert = $node['Webhook: fraud-alert'].json.body;
const kyc = $node['Fetch KYC Profile'].json;
const ledger = $node['Fetch 30d Ledger'].json;
const devices = $node['Fetch Device Fingerprints'].json;
const sanctions = $node['Sanctions Check (3x parallel)'].json;
return [{
  json: {
    alert_id: alert.alert_id,
    player_id: alert.player_id,
    severity: alert.severity,
    triggered_at: alert.triggered_at,
    kyc: kyc,
    ledger_30d_summary: {
      events: ledger.length || 0,
      total_deposits: ledger.filter(e => e.type === 'DEPOSIT').reduce((s, e) => s + Number(e.amount), 0),
      total_withdrawals: ledger.filter(e => e.type === 'WITHDRAWAL').reduce((s, e) => s + Number(e.amount), 0),
    },
    device_count: devices.length || 0,
    sanctions_hits: sanctions.matches || [],
    composite_risk_score: (alert.score || 0) + (sanctions.matches?.length ? 50 : 0),
  }
}];

